window.DOSIK=window.DOSIK||{};DOSIK["yc_devpsych"]={"1":[{"t":"vs","title":"발달 관점","cols":[{"name":"전 생애발달","items":["발달은 생명의 시작에서 죽음에 이르기까지의 전 생애 동안 이루어지는 모든 과정이다","모든 연령에서의 발달은 성장과 감소의 변화가 함께 일어난다","노년기에도 가소성(plasticity)으로 인해 훈련과 연습을 하면 다양한 기술을 향상시킬 수 있다"]},{"name":"불연속성","items":["발달을 구별되는 단계로 일어나는 질적 변화의 과정으로 본다"]}]},{"t":"tree","title":"발달의 원리","root":"발달","branches":[["유전과 환경","발달은 유전과 환경의 상호작용 결과이다"],["방향","머리에서 발 방향으로 진행된다"],["영역","인지적, 사회정서적, 신체적 발달은 상호작용한다"],["맥락","역사적 혹은 문화적 맥락은 발달에 영향을 미친다 · 코로나 팬데믹은 규범적 역사관련 요인이다"]]},{"t":"table","title":"발달 개념","head":["개념","뜻"],"rows":[["규준적(normative) 발달","전형적이고 평균적인 발달을 말한다"],["가소성(plasticity)","경험에 반응하여 변화하는 능력을 의미한다"]]}],"2":[{"t":"table","title":"발달연구 방법","head":["방법","특징"],"rows":[["관찰법","관찰자가 자신이 원하는 방식으로 관찰 자료를 수집하고 해석하는 관찰자 편향이 나타날 수 있다"],["실험연구","두 변수 간 원인과 결과의 관계를 알 수 있다 · 독립변수와 종속변수 간의 인과관계를 파악한다"],["상관연구","둘 이상의 변수 간 관계를 상관계수로 표현한다"],["횡단적 연구법","동시에 각기 다른 연령의 사람들을 비교하여 연구하는 방법이다"],["종단적 연구법","단점으로는 피험자 탈락, 편파적 표집 및 연습효과 등을 들 수 있다 · 연구 과정에서 피험자 탈락, 연습효과 등이 연구결과를 왜곡할 수 있다"],["계열적 설계","여러 연령집단을 표집하여 일정한 기간 동안 반복 관찰한다"]]},{"t":"tree","title":"연구윤리","root":"연구윤리","branches":[["사전 동의","사전 동의를 받았더라도 연구 과정에서 예기치 못한 위협이 발생할 경우 연구자는 즉시 연구를 중단해야 한다"],["동등한 처치","연구에 참여하는 모든 참여자는 다른 참여자들이 받는 유익한 처치를 동등하게 받을 권리가 있다"],["사생활","연구 참여자들은 사생활을 보호받을 권리가 있으며 개인 정보는 철저히 보호되어야 한다"],["아동","아동은 취약한 피험자이므로 기관생명윤리위원회의 정규심의를 거쳐야 하며 연구윤리 원칙이 엄격하게 지켜져야 한다"]]}],"3":[{"t":"table","title":"발달이론가","head":["이론가","주장"],"rows":[["에릭슨(E. Erikson)","특정 발달 단계에서의 위기 극복에 실패하더라도 다음 단계로 발달이 진행된다"],["비고츠키(L. Vygotsky)","아동의 발달을 사회적 상호작용과 문화로부터 분리할 수 없다"],["브론펜브레너(U. Bronfenbrenner)","개인과 생태학적 체계 간의 관계는 양방향적이다"],["설리반(H. Sullivan)","질풍노도의 시기는 성ㆍ친밀감ㆍ안전 욕구 간의 충돌로 인해 일어난다"],["수퍼(D. Super)","진로발달 과정에서 자아개념은 중요한 요인이다"]]}],"4":[{"t":"tree","title":"정신분석 이론","root":"정신분석이론과 성격발달","branches":[["의식 수준","인간의 정신적 지각 수준인 무의식, 전의식, 의식의 세 영역 중 무의식 세계를 가장 중시한다"],["결정론","인간의 모든 행동에는 그 원인이 있다는 심리적 결정론을 주장한다"],["성격발달","다섯 단계로 이루어지는 성격발달단계는 누구든 차례대로 거치게 된다"],["방어기제","방어기제를 습관적으로 반복 사용하는 것은 건강하지 못한 성격의 징표로 볼 수 있다"]]},{"t":"table","title":"방어기제","head":["관점","내용"],"rows":[["베이런트","프로이트(S. Freud)의 방어기제 중에는 더 성숙한 방어기제도 있다고 간주 · 시련이나 위기에 직면한 개인이 나타내는 심리적 적응방식에서의 발달적 변화에 관심"],["성공적인 사람들","개인생활과 직업생활에서 미성숙한 방어기제보다는 더 성숙한 방어기제를 사용하는 쪽으로 이동"],["정신병적 방어기제","망상적 투사, 부정, 왜곡이 대표적 유형"],["주지화(intellectualization)","종교, 문학 등의 지적 활동에 몰입함으로써 불안을 회피하려는 것"]]}],"6":[{"t":"tree","title":"지능 특성","root":"지능의 특성","branches":[["문제","새로운 문제를 다루는 능력이다"],["공간","공간지각 및 추론 능력과 관련된다"],["노화","성인 중기 전후에 퇴보하기 시작한다"],["유전","유전적 요인에 의해 결정되는 지능이다"]]},{"t":"table","title":"지능이론","head":["이론가","내용"],"rows":[["서스톤(I. Thurstone)의 기초정신능력이론","지능은 상호 독립적인 일곱 가지 하위요인으로 구성됨"],["카텔(R. Cattell)의 Gf-Gc이론","결정적 지능(Gc)은 성인기에도 다양한 지적 자극을 통해 유지 되거나 향상될 수 있음"],["스피어만(C. Spearman)의 이요인이론","일반요인(g)은 모든 유형의 지적 활동에 관여하는 일반적 능력임"],["가드너(H. Gardner)의 다중지능이론","지능은 문화권에 따라 다르게 정의될 수 있으며 각 하위 지능들의 상대적 중요성은 동일함 · 여러 개의 독립적인 지능들로 구성되어 있다"]]}],"8":[{"t":"tree","title":"태내발달","root":"태내발달","branches":[["태아기","임신 2개월부터 출생까지의 시기이다"],["생존 가능","임신 28주경이 되면 태아는 자궁 밖에서 생존 가능하다"],["배아기","기형유발물질에 의한 중추신경계 손상에 가장 민감한 시기이다"],["뉴런","태아기 동안 실제로 필요한 뉴런보다 훨씬 더 많은 뉴런이 생성된다"]]}],"9":[{"t":"table","title":"신생아 반사","head":["반사","내용"],"rows":[["반사 행동","신생아는 출생 직후부터 외부 자극에 무의식적으로 반응한다"],["모로 반사","갑자기 위치가 바뀌거나 큰 소리가 들리면 나타난다"],["바빈스키 반사","신생아의 발바닥을 간지럽히면 발가락을 부채처럼 쫙 펴는 반사이다"],["생존 반사","눈 깜박이기 반사나 호흡 반사와 같은 생존 반사는 평생 유지된다"]]},{"t":"tree","title":"영아기 뇌신경계","root":"뇌 발달","branches":[["변연계","변연계 중 편도체는 정서와 감정을 관장한다 · 투쟁-도피 반응은 교감신경계 활성화와 관계있다"],["시냅스","시각피질의 시냅스 생성은 출생 후 1년까지 활발하게 진행된다 · 영아는 성인보다 많은 수의 시냅스를 갖고 있다"],["전전두엽","출생 이후 전전두엽 피질의 활성화로 인지적 통제기능이 점차 향상된다"],["성장","청소년기보다 영아기에 뇌의 성장 급등이 이루어진다 · 대뇌 피질의 발달은 영아기 이후에도 진행된다 · 영아의 뇌는 성인의 뇌보다 가소성이 뛰어나다"]]}],"11":[{"t":"table","title":"언어발달","head":["개념","내용"],"rows":[["어휘발달 초기","과잉확장과 과잉축소의 특성이 나타난다"],["생득주의 접근","인간은 언어습득장치를 가지고 태어난다고 주장한다"],["베르니케(Wernicke) 실어증","언어를 이해하는 데 문제가 발생하는 장애이다"],["화용론(pragmatics)","사회적 맥락에서 언어를 적절하고 효과적으로 사용하는 규칙에 관한 지식이다"]]}],"12":[{"t":"table","title":"양육방식","head":["양육방식","특징"],"rows":[["권위적(authoritative)","자녀의 사회적 유능감을 높인다"],["허용적(permissive)","자녀의 행동을 수용은 하지만 통제하지 않는다"],["방임적(uninvolved)","자녀에게 관심을 갖지 않고 자녀의 삶에 관여하지 않는다"]]},{"t":"tree","title":"정서발달","root":"정서발달","branches":[["공포","위험에 대한 반응으로 나타난다"],["이차 정서","자아의 인식 이후에 나타난다"],["만족지연","연령이 증가할수록 만족지연 능력이 증가한다"],["정서 구별","유아는 사람들이 진짜로 느끼는 정서와 그들이 표현하는 정서를 잘 구별하지 못한다"]]},{"t":"tree","title":"애착","root":"애착","branches":[["저항애착아","주양육자에게 양가적 태도를 보인다"],["볼비(J. Bowlby)","애착형성을 본능적 반응의 결과로 설명한다"],["분리불안","영아가 애착 대상에게서 떨어질 때 나타나는 불안반응이다"],["대상영속성","애착을 형성하기 위해서는 대상영속성이 획득되어야 한다"]]}],"14":[{"t":"tree","title":"공격성","root":"공격성","branches":[["닷지(K. Dodge)","공격성이 잘못된 사회인지적 판단에 기인한다고 본다"],["적대적 공격성","타인에게 고통이나 해를 가하는 것 자체가 목적이다"],["영아","영아의 공격성은 대체로 물건을 차지하기 위한 도구적 공격성이다"],["보상이론가","공격적 행동은 그러한 행동이 결과적으로 공격자에게 보상을 가져다주기 때문에 발달한다고 주장한다"]]},{"t":"table","title":"친사회적 행동","head":["이론","내용"],"rows":[["정신분석이론","친사회적 행동은 초자아의 발달과 관련되어 있다"],["사회교환이론","친사회적 행동으로 인한 손해가 보상보다 클 때 친사회적 행동은 감소한다"],["사회학습이론","친사회적 행동에 대한 보상의 관찰은 친사회적 행동을 증진시킨다"],["이타적 행동","유아기보다 아동기에 더 많이 발생한다"]]}],"16":[{"t":"tree","title":"청소년기 인지","root":"청소년기 인지발달","branches":[["형식적 사고","명제적 사고와 가설 연역적인 논리적 사고를 할 수 있다"],["조합적 추리","문제 해결에 필요한 요인만 골라내어 체계적으로 조합, 구성하는 조합적 추리 능력이 발달한다"],["자의식","자의식을 지나치게 과장한 나머지 자신의 행동이 모든 사람의 관심 대상이라고 생각한다"],["관점","자신과 상대방의 관점을 사회적 가치체계에 의해 판단할 수 있게 된다"]]}],"18":[{"t":"table","title":"성인기·노년기 이론","head":["이론가·이론","내용"],"rows":[["페리(W. Perry)","이원적 사고에서 상대적 사고로 옮겨 간다고 본다"],["에릭슨(E. Erikson)","8단계인 노년기에 발달되는 바람직한 미덕으로 지혜를 제안한다"],["레빈슨(D. Levinson)","노년기를 ‘다리 위에서의 조망(one's view from the bridge)’이라 표현 한다 · 남성을 대상으로 연구한 결과를 근거로 하였다"],["유리 이론(disengagement theory)","노인과 사회의 상호 철회 과정을 부정적으로 보지 않고 성공적 노화로 본다"],["활동 이론(activity theory)","근로자, 부모 등 개인의 역할이 삶에서 만족을 얻을 수 있는 주요 원천으로 본다"]]}],"19":[{"t":"tree","title":"자폐스펙트럼장애","root":"자폐스펙트럼장애","branches":[["상호작용","사회적ㆍ정서적 상호작용에서 결함을 보인다"],["행동 양식","제한적이고 반복적인 행동 양식과 흥미, 활동을 보인다"],["마음이론","마음이론을 발달시키지 못해 다른 사람의 관점을 잘 이해하지 못한다"],["조기 개입","조기발견과 개입을 하게 되면 자폐스펙트럼장애가 지적장애로 이어지는 비율을 감소시킬 수 있다"]]},{"t":"table","title":"진단 기준","head":["기준","내용"],"rows":[["증상 수","진단을 위한 증상 9개 중 6개 이상이 최소 6개월 동안 발달수준에 적합하지 않아야 한다"],["환경","진단의 지표가 되는 증상 9개 중 몇 개는 2개 이상의 환경(가정, 학교, 대인관계 등)에서 나타난다"],["시기","진단의 지표가 되는 증상 9개 중 몇 개는 12세 이전에 나타난다"],["기능","증상이 사회적ㆍ학업적 또는 직업적 기능의 질을 방해하거나 감소시킨다는 명확한 증거가 있다"]]},{"t":"def","term":"말을 하지 않는 것","text":"언어에 대한 지식의 부족으로 말을 하지 않는 것이 아니다"}]};
